def earliest(n, edges, allow_same_time):
    graph = [[] for _ in range(n + 1)]
    for u, v, p, t in edges:
        graph[u].append((v, p, t))
    dist = [float('\\''inf'\\'')] * (n + 1)
    dist[1] = 0
    heap = [(0, 1)]
    while heap:
        at, u = heappop(heap)
        if at "'!= dist[u]:
            continue
        for v, p, t in graph[u]:
            if allow_same_time or (u == 1 and at == 0):
                departure = ((at + p - 1) // p) * p
            else:
                departure = (at // p + 1) * p
            arrival = departure + t
            if arrival < dist[v]:
                dist[v] = arrival
                heappush(heap, (arrival, v))
    return -1 if dist[n] == float('"'\\''inf'\\'') else dist[n]

cases = [
    ('\\''official sample'\\'', 3, [(1, 2, 3, 1), (2, 3, 2, 4)]),
    ('\\''same-time transfer witness'\\'', 3, [(1, 2, 2, 2), (2, 3, 2, 1)]),
    ('\\''no edges'\\'', 2, []),
]
for name, n, edges in cases:
    print(name, {'\\''same_time_allowed'\\'': earliest(n, edges, True), '\\''same_time_disallowed_after_arrival'\\'': earliest(n, edges, False)})
'"

